-- ============================================
-- LUMA — Thème 13 : LONG 1/3 x4 — Une conférence sur deux jours avec plusieurs rencontres clés
-- ============================================


update scenarios set content = '{"characters": {"organizer": "l''organisateur", "mira": "Mira", "narrator": "narrateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "organizer", "text": "Welcome to day one! Feel free to explore the sessions and network during breaks.", "text_fr": "Bienvenue au jour un ! N''hésitez pas à explorer les sessions et à réseauter pendant les pauses.", "choices": [{"text": "Thank you, I''m excited to see what today brings.", "text_fr": "Merci, j''ai hâte de voir ce qu''aujourd''hui apporte.", "next": "n2"}, {"text": "Could you recommend which sessions are must-attend today?", "text_fr": "Vous pourriez recommander quelles sessions sont incontournables aujourd''hui ?", "next": "n2b"}]}, "n2": {"speaker": "organizer", "text": "The innovation panel this morning is expected to be quite popular.", "text_fr": "Le panel innovation ce matin devrait être assez populaire.", "choices": [{"text": "I''ll make sure to attend that one then.", "text_fr": "Je vais m''assurer d''y assister alors.", "next": "n3"}]}, "n2b": {"speaker": "organizer", "text": "Definitely the innovation panel this morning, and the closing keynote tonight.", "text_fr": "Définitivement le panel innovation ce matin, et le discours de clôture ce soir.", "choices": [{"text": "Perfect, I''ll plan my day around those.", "text_fr": "Parfait, je vais planifier ma journée autour de ça.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(During the innovation panel, you strike up a conversation with the person next to you.)", "text_fr": "(Pendant le panel innovation, vous engagez une conversation avec la personne à côté de vous.)", "choices": [{"text": "This panel is fascinating so far, don''t you think?", "text_fr": "Ce panel est fascinant jusqu''ici, vous trouvez pas ?", "next": "n4"}]}, "n4": {"speaker": "mira", "text": "Absolutely! I''m Mira, by the way. I run a small startup in renewable energy.", "text_fr": "Absolument ! Je m''appelle Mira, au fait. Je dirige une petite startup dans l''énergie renouvelable.", "choices": [{"text": "That''s impressive! I''d love to hear more about what you''re building.", "text_fr": "C''est impressionnant ! J''aimerais en savoir plus sur ce que vous construisez.", "next": "n5"}]}, "n5": {"speaker": "mira", "text": "We''re developing more efficient solar storage solutions. Still early days, but promising.", "text_fr": "On développe des solutions de stockage solaire plus efficaces. Encore les débuts, mais prometteur.", "choices": [{"text": "That sounds like exactly the kind of innovation this conference celebrates.", "text_fr": "Ça ressemble exactement au genre d''innovation que cette conférence célèbre.", "next": "n6"}]}, "n6": {"speaker": "mira", "text": "Thank you! Let''s definitely stay in touch — I have a feeling we''ll cross paths again.", "text_fr": "Merci ! Restons définitivement en contact — j''ai le sentiment qu''on va se recroiser.", "choices": [{"text": "I hope so too. Enjoy the rest of day one!", "text_fr": "Je l''espère aussi. Profitez du reste du jour un !", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(Later that evening, at the closing reception, you spot Mira again across the room.)", "text_fr": "(Plus tard ce soir-là, à la réception de clôture, vous repérez Mira à nouveau de l''autre côté de la salle.)", "choices": [{"text": "(Approach Mira again, curious to continue the conversation.)", "text_fr": "(Approche Mira à nouveau, curieux de continuer la conversation.)", "next": "n8"}]}, "n8": {"speaker": "mira", "text": "Oh, hey again! Actually, I wanted to ask — are you attending tomorrow''s investor pitch session?", "text_fr": "Oh, salut encore ! En fait, je voulais demander — vous assistez à la session de pitch investisseurs demain ?", "choices": [{"text": "I hadn''t planned to, but now I''m curious. Are you presenting?", "text_fr": "J''avais pas prévu, mais maintenant je suis curieux. Vous présentez ?", "next": "n9"}]}, "n9": {"speaker": "mira", "text": "I am! I''d love to have a friendly face in the audience, if you''re free.", "text_fr": "Oui ! J''adorerais avoir un visage amical dans le public, si vous êtes libre.", "choices": [{"text": "I''ll definitely be there to support you. Good luck preparing tonight!", "text_fr": "Je serai définitivement là pour vous soutenir. Bonne chance pour la préparation ce soir !", "next": "n10"}]}, "n10": {"speaker": "narrator", "text": "(Day two arrives. You make your way to the investor pitch session as promised.)", "text_fr": "(Le jour deux arrive. Vous vous rendez à la session de pitch investisseurs comme promis.)", "choices": [{"text": "(Take a seat near the front to show your support.)", "text_fr": "(Prends place près du devant pour montrer ton soutien.)", "next": "n11"}]}, "n11": {"speaker": "mira", "text": "(Spots you in the crowd, visibly relieved) There you are! Thanks for coming.", "text_fr": "(Te repère dans la foule, visiblement soulagée) Te voilà ! Merci d''être venu.", "choices": [{"text": "Of course, you''ve got this. Good luck!", "text_fr": "Bien sûr, vous allez y arriver. Bonne chance !", "next": "n12"}]}, "n12": {"speaker": "narrator", "text": "(Mira delivers a confident, compelling pitch, and the investors seem genuinely impressed.)", "text_fr": "(Mira livre un pitch confiant et convaincant, et les investisseurs semblent vraiment impressionnés.)", "choices": [{"text": "(Applaud enthusiastically as she finishes.)", "text_fr": "(Applaudis avec enthousiasme quand elle termine.)", "next": "n13"}]}, "n13": {"speaker": "mira", "text": "(Finding you afterward, beaming) I think that actually went really well!", "text_fr": "(Te retrouvant après, rayonnante) Je pense que ça s''est vraiment bien passé !", "choices": [{"text": "It was fantastic! Your passion for this really came through.", "text_fr": "C''était fantastique ! Votre passion pour ça est vraiment ressortie.", "next": "n14"}]}, "n14": {"speaker": "mira", "text": "Thank you for being here for this. Honestly, having support made a real difference.", "text_fr": "Merci d''avoir été là pour ça. Honnêtement, avoir du soutien a fait une vraie différence.", "choices": [{"text": "That''s what conferences like this are really about — genuine connections.", "text_fr": "C''est ça que les conférences comme ça représentent vraiment — de vraies connexions.", "next": "end_supported"}]}, "end_supported": {"speaker": "mira", "text": "Couldn''t agree more. This has been an incredible two days, largely thanks to meeting you.", "text_fr": "Je suis totalement d''accord. Ça a été deux jours incroyables, en grande partie grâce à notre rencontre.", "end": true, "ending_label": "Deux jours de conférence, une connexion précieuse née 🎤🤝"}}}'::jsonb, is_playable = true
where title = 'Une conférence sur deux jours avec plusieurs rencontres clés'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
